INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Disposition nur für physische Ressourcen gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch digitale Ressourcen"}, {"text": "Ja", "correct": false, "because": "IT-Ressourcen eingeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Disposition in einem IT-System?', 3, '[{"text": "Effiziente Ressourcennutzung", "correct": true, "because": "Optimierung"}, {"text": "Kosten erhöhen", "correct": false, "because": "Senkung im Fokus"}, {"text": "Hardware ersetzen", "correct": false, "because": "Nutzung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressourcen werden in der Disposition verwaltet?', 5, '[{"text": "Serverkapazität", "correct": true, "because": "IT-Ressource"}, {"text": "Bandbreite", "correct": true, "because": "Netzwerk"}, {"text": "Büromöbel", "correct": false, "because": "Kein IT-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Disposition plant Ressourcen. b) Sie ersetzt Monitoring.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Monitoring ergänzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Disposition von IT-Ressourcen?', 4, '[{"text": "Verfügbarkeit", "correct": false, "because": "Kernaspekt"}, {"text": "Lastverteilung", "correct": false, "because": "Wichtig"}, {"text": "Farbe der Server", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Disposition nur für Hardware gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software"}, {"text": "Ja", "correct": false, "because": "Breiterer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft bei der Disposition von Ressourcen?', 3, '[{"text": "Monitoring-Software", "correct": true, "because": "Ressourcennutzung"}, {"text": "Texteditor", "correct": false, "because": "Kein Planungstool"}, {"text": "Browser", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Disposition wichtig?', 5, '[{"text": "Kapazitätsplanung", "correct": true, "because": "Ressourcenbedarf"}, {"text": "Priorisierung", "correct": true, "because": "Effiziente Nutzung"}, {"text": "Papierverbrauch", "correct": false, "because": "Kein IT-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Disposition optimiert IT-Systeme. b) Sie ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch KMUs"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Disposition?', 4, '[{"text": "Ressourcenübersicht", "correct": false, "because": "Grundlage"}, {"text": "Planungstools", "correct": false, "because": "Unterstützung"}, {"text": "Kaffeemaschine", "correct": true, "because": "Kein IT-Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Disposition dasselbe wie Provisionierung?', 2, '[{"text": "Nein", "correct": true, "because": "Disposition plant"}, {"text": "Ja", "correct": false, "because": "Provisionierung stellt bereit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressourcen werden in der IT-Disposition priorisiert?', 4, '[{"text": "CPU-Leistung", "correct": true, "because": "Kritisch"}, {"text": "Speicherplatz", "correct": true, "because": "Wichtig"}, {"text": "Bürostühle", "correct": false, "because": "Kein IT-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Disposition nur für Server ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Netzwerke"}, {"text": "Ja", "correct": false, "because": "Breiterer Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Disposition?', 3, '[{"text": "Effizienz", "correct": true, "because": "Optimale Nutzung"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "Automatisierung"}, {"text": "Optisches Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Disposition plant Ressourcen. b) Sie ignoriert Lastspitzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lastspitzen berücksichtigt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Disposition?', 5, '[{"text": "Weniger Ausfälle", "correct": true, "because": "Ressourcen verfügbar"}, {"text": "Kosteneffizienz", "correct": true, "because": "Optimierte Nutzung"}, {"text": "Mehr Hardware", "correct": false, "because": "Nutzung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Disposition unwichtig?', 3, '[{"text": "Verfügbarkeit", "correct": false, "because": "Kernaspekt"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig"}, {"text": "Schriftart", "correct": true, "because": "Kein IT-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Disposition automatisiert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Tools unterstützen"}, {"text": "Nein", "correct": false, "because": "Automatisierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Disposition nur für Admins ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Management"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für Disposition zentral?', 4, '[{"text": "Ressourcenplanung", "correct": true, "because": "Kernaufgabe"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisierung"}, {"text": "Papierdokumente", "correct": false, "because": "Digital"}]');
